/* ===========================================================
 * idb-keyval · minimal browser bundle (Phase 3)
 * ------------------------------------------------------------
 * Tiny IndexedDB key-value wrapper. Replaces the upstream
 * idb-keyval UMD bundle, which fails to expose window.idbKeyVal
 * when loaded via <script> in modern browsers (the UMD path
 * prefers globalThis.idbKeyval assignment but the wrapper
 * argument wiring leaves the namespace undefined).
 *
 * Exposes: window.idbKeyVal = { createStore, get, set, del, keys, values, clear }
 * Each function takes a store as last arg; default store is "keyval-store/kv".
 * =========================================================== */
(function (root) {
  'use strict';
  if (root.idbKeyVal) return;  // already polyfilled

  function promisifyRequest(req) {
    return new Promise(function (resolve, reject) {
      req.oncomplete = req.onsuccess = function () { resolve(req.result); };
      req.onabort = req.onerror = function () { reject(req.error); };
    });
  }

  function createStore(dbName, storeName) {
    var request = indexedDB.open(dbName);
    request.onupgradeneeded = function () {
      if (!request.result.objectStoreNames.contains(storeName)) {
        request.result.createObjectStore(storeName);
      }
    };
    var dbPromise = promisifyRequest(request);

    return function (mode, fn) {
      return dbPromise.then(function (db) {
        return fn(db.transaction(storeName, mode).objectStore(storeName));
      });
    };
  }

  var defaultGetStore = createStore('keyval-store', 'kv');
  var defaultStore = function (mode, fn) {
    return defaultGetStore(mode, function (s) { return fn(s); });
  };

  function get(key, store) {
    return (store || defaultStore)('readonly', function (s) {
      return promisifyRequest(s.get(key));
    });
  }
  function set(key, val, store) {
    return (store || defaultStore)('readwrite', function (s) {
      s.put(val, key);
      return promisifyRequest(s.transaction);
    });
  }
  function del(key, store) {
    return (store || defaultStore)('readwrite', function (s) {
      s.delete(key);
      return promisifyRequest(s.transaction);
    });
  }
  function clear(store) {
    return (store || defaultStore)('readwrite', function (s) {
      s.clear();
      return promisifyRequest(s.transaction);
    });
  }
  function keys(store) {
    return (store || defaultStore)('readonly', function (s) {
      if (s.getAllKeys) return promisifyRequest(s.getAllKeys());
      return new Promise(function (resolve, reject) {
        var out = [];
        s.openCursor().onsuccess = function (e) {
          var c = e.target.result;
          if (c) { out.push(c.key); c.continue(); }
          else resolve(out);
        };
        s.openCursor().onerror = function (e) { reject(e.target.error); };
      });
    });
  }
  function values(store) {
    return (store || defaultStore)('readonly', function (s) {
      if (s.getAll) return promisifyRequest(s.getAll());
      return new Promise(function (resolve, reject) {
        var out = [];
        s.openCursor().onsuccess = function (e) {
          var c = e.target.result;
          if (c) { out.push(c.value); c.continue(); }
          else resolve(out);
        };
        s.openCursor().onerror = function (e) { reject(e.target.error); };
      });
    });
  }

  root.idbKeyVal = {
    createStore: createStore,
    get: get,
    set: set,
    del: del,
    clear: clear,
    keys: keys,
    values: values,
    promisifyRequest: promisifyRequest,
  };
})(typeof window !== 'undefined' ? window : globalThis);
